INSERT INTO `v1_3be06ec61aff759830f994edeba20acbf200be31cd97b51cdb66abd85655965e` VALUES (0, 0, 101, 1, "高い物理攻撃力を宿し、強力な範囲攻撃を行うよう\nプログラムされたボスが現れる。", 1, "ガーゴイル", "剛力なる鳥像");
INSERT INTO `v1_3be06ec61aff759830f994edeba20acbf200be31cd97b51cdb66abd85655965e` VALUES (0, 0, 102, 2, "高い魔法攻撃力を宿し、強力な範囲攻撃を行うよう\nプログラムされたボスが現れる。", 2, "マグスガーゴイル", "魔業なる鳥像");
INSERT INTO `v1_3be06ec61aff759830f994edeba20acbf200be31cd97b51cdb66abd85655965e` VALUES (0, 0, 103, 3, "防御力アップスキルで高い耐久力を誇り、相手の攻撃\nを凌ぐようプログラムされたボスが現れる。", 3, "ガードガーゴイル", "堅固なる鳥像");
INSERT INTO `v1_3be06ec61aff759830f994edeba20acbf200be31cd97b51cdb66abd85655965e` VALUES (202, 0, 101, 4, "高い物理攻撃力を宿し、強力な範囲攻撃を行うよう\nプログラムされたマルチターゲットのボスが現れる。", 4, "ガーゴイル・バースト", "剛力の浮石を従えし鳥像");
INSERT INTO `v1_3be06ec61aff759830f994edeba20acbf200be31cd97b51cdb66abd85655965e` VALUES (202, 0, 102, 5, "高い魔法攻撃力を宿し、強力な範囲攻撃を行うよう\nプログラムされたマルチターゲットのボスが現れる。", 5, "ガーゴイル・マギ", "魔業の浮石を従えし鳥像");
